const canvas=document.getElementById('stage'),ctx=canvas.getContext('2d');
const W=960,H=540,GROUND=430;
const cast=[
 {name:'Bung Karno',tag:'Sang Proklamator',skill:'Pidato Menggelegar',icon:'🎩',coat:'#f1e7d0',trim:'#c73f35',skin:'#bd7855',hat:true,glow:'#ffce62'},
 {name:'Bung Hatta',tag:'Bapak Koperasi',skill:'Langkah Diplomasi',icon:'👓',coat:'#d8e1de',trim:'#426b78',skin:'#a96d4d',hat:true,glow:'#80d6bf'},
 {name:'Ibu Kartini',tag:'Pelita Emansipasi',skill:'Selendang Cakrawala',icon:'🌺',coat:'#bd6881',trim:'#f5ca7a',skin:'#c98768',hat:false,glow:'#fa91b1'},
 {name:'Ki Hajar',tag:'Bapak Pendidikan',skill:'Tameng Tuntunan',icon:'📚',coat:'#856345',trim:'#d8b274',skin:'#a96e4f',hat:true,glow:'#a9c2ff'},
 {name:'Jenderal Sudirman',tag:'Panglima Besar',skill:'Komando Kilat',icon:'⭐',coat:'#73896b',trim:'#e2c47d',skin:'#b77e61',hat:true,glow:'#b4e17d'},
 {name:'Cut Nyak Dien',tag:'Srikandi Aceh',skill:'Putaran Rencong',icon:'🌙',coat:'#324a55',trim:'#dbb86e',skin:'#a86d53',hat:false,glow:'#8bd7dd'}
];
let selected=0,enemyIndex=1,active=false,last=0,elapsed=0,timeLeft=60,shake=0,flashText=0,particles=[];
const keys={left:false,right:false,jump:false,attack:false,special:false};
let player,enemy;
const $=id=>document.getElementById(id);
function makeFighter(x,dir,data,isCPU){return{x,y:GROUND,vx:0,vy:0,dir,hp:100,energy:100,data,isCPU,attack:null,cool:0,stun:0,flash:0,walk:0,aiWait:.7,block:false}}
function setCards(){enemyIndex=(selected+1)%cast.length;$('pcard').textContent=cast[selected].name;$('picon').textContent=cast[selected].icon;$('pskill').textContent='Jurus: '+cast[selected].skill;$('ecard').textContent=cast[enemyIndex].name;$('eicon').textContent=cast[enemyIndex].icon}
$('prev').onclick=()=>{selected=(selected+cast.length-1)%cast.length;setCards()};$('next').onclick=()=>{selected=(selected+1)%cast.length;setCards()};
function startGame(){player=makeFighter(320,1,cast[selected],false);enemy=makeFighter(640,-1,cast[enemyIndex],true);elapsed=0;timeLeft=60;active=true;particles=[];keys.attack=keys.special=false;$('menu').style.display='none';$('result').style.display='none';$('hud').style.display='block';$('hint').style.display='block';$('pname').textContent=player.data.name;$('ename').textContent=enemy.data.name;message('MULAI!');setTimeout(()=>{if(active)$('message').style.display='none'},900);updateHUD()}
$('start').onclick=startGame;$('again').onclick=startGame;
function message(text){const e=$('message');e.textContent=text;e.style.display='block';e.style.animation='none';void e.offsetWidth;e.style.animation='pop .25s ease-out'}
function endGame(winner){if(!active)return;active=false;const won=winner==='player';$('result-title').textContent=winner==='draw'?'SERI!':won?'MENANG!':'KALAH!';$('result-title').style.color=winner==='draw'?'#ffc95b':won?'#83d6bd':'#ed7665';$('result-copy').textContent=winner==='draw'?'Waktu habis, wibawa kalian seimbang.':won?`${player.data.name} menguasai panggung Nusantara!`:`${enemy.data.name} kali ini lebih unggul. Coba lagi!`;$('result').style.display='grid'}
function updateHUD(){$('php').style.width=Math.max(0,player.hp)+'%';$('ehp').style.width=Math.max(0,enemy.hp)+'%';$('pep').style.width=player.energy+'%';$('eep').style.width=enemy.energy+'%';$('timer').textContent=Math.ceil(timeLeft)}
function setKey(code,on){if(code==='KeyA'||code==='ArrowLeft')keys.left=on;if(code==='KeyD'||code==='ArrowRight')keys.right=on;if(code==='KeyW'||code==='ArrowUp'||code==='Space')keys.jump=on;if(code==='KeyJ'||code==='KeyF')keys.attack=on;if(code==='KeyK'||code==='KeyG')keys.special=on}
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','Space'].includes(e.code))e.preventDefault();if(e.repeat)return;setKey(e.code,true);if(!active&&(e.code==='Enter'||e.code==='Space')&&$('menu').style.display!=='none')startGame()});window.addEventListener('keyup',e=>setKey(e.code,false));
document.querySelectorAll('.ctrl').forEach(btn=>{const key=btn.dataset.key;const down=e=>{e.preventDefault();keys[key]=true;btn.classList.add('held')},up=e=>{e.preventDefault();keys[key]=false;btn.classList.remove('held')};btn.addEventListener('pointerdown',down);['pointerup','pointercancel','pointerleave'].forEach(ev=>btn.addEventListener(ev,up))});
function beginAttack(f,type){if(f.cool>0||f.stun>0||f.attack)return;if(type==='special'){if(f.energy<35)return;f.energy-=35;f.attack={type,t:.48,hit:false};f.cool=.72}else{f.attack={type,t:.29,hit:false};f.cool=.42}}
function attackCheck(a,b){if(!a.attack||a.attack.hit)return;const duration=a.attack.type==='special'?.48:.29,progress=1-a.attack.t/duration;if(progress<.38)return;const range=a.attack.type==='special'?126:82;if(Math.abs(a.x-b.x)<range&&Math.abs(a.y-b.y)<85&&a.dir===Math.sign(b.x-a.x)){a.attack.hit=true;const guarded=b.block&&b.dir===Math.sign(a.x-b.x);const damage=(a.attack.type==='special'?22:10)*(guarded?.3:1);b.hp=Math.max(0,b.hp-damage);b.stun=guarded?.12:.23;b.flash=.18;shake=a.attack.type==='special'?9:4;const push=guarded?5:12;b.x+=a.dir*push;if(a.attack.type==='special'){burst((a.x+b.x)/2,b.y-70,a.data.glow,16);banner(a.x,a.y-86,a.data.glow)}else burst(b.x,b.y-70,'#ffe0a2',7);if(b.hp<=0)endGame(a===player?'player':'enemy')}}
function banner(x,y,color){particles.push({kind:'ring',x,y,color,life:.34,max:.34})}
function burst(x,y,color,count){for(let i=0;i<count;i++){const angle=Math.random()*Math.PI*2,speed=40+Math.random()*180;particles.push({kind:'spark',x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed-30,life:.25+Math.random()*.35,max:.6,color,size:2+Math.random()*5})}}
function ai(dt){const dx=player.x-enemy.x,dist=Math.abs(dx);enemy.dir=dx>=0?1:-1;enemy.block=player.attack&&dist<105&&Math.random()<.05;if(dist>100){enemy.vx=Math.sign(dx)*105}else enemy.vx=0;enemy.aiWait-=dt;if(enemy.aiWait<=0&&dist<144){if(enemy.energy>=35&&Math.random()<.33)beginAttack(enemy,'special');else beginAttack(enemy,'normal');enemy.aiWait=.56+Math.random()*.55}if(dist>290&&Math.random()<dt*.22&&enemy.y>=GROUND)enemy.vy=-430}
function updateFighter(f,dt,opponent){f.cool=Math.max(0,f.cool-dt);f.stun=Math.max(0,f.stun-dt);f.flash=Math.max(0,f.flash-dt);if(f.attack){f.attack.t-=dt;if(f.attack.t<=0)f.attack=null}
if(f.isCPU)ai(dt);else{f.block=keys.left&&Math.abs(f.x-opponent.x)<95&&f.dir===Math.sign(opponent.x-f.x)&&!keys.attack;f.vx=f.stun?0:(keys.left&&!f.block?-190:0)+(keys.right?190:0);if(keys.jump&&f.y>=GROUND-1&&!f.stun)f.vy=-435;if(keys.attack)beginAttack(f,'normal');if(keys.special)beginAttack(f,'special')}
if(f.y<GROUND||f.vy<0){f.vy+=1050*dt;f.y+=f.vy*dt;if(f.y>=GROUND){f.y=GROUND;f.vy=0}}f.x+=f.vx*dt;f.x=Math.max(85,Math.min(875,f.x));if(!f.attack&&!f.stun&&!f.block&&Math.abs(f.vx)>1)f.walk+=dt*9;if(!f.isCPU&&Math.abs(f.vx)>1)f.dir=Math.sign(opponent.x-f.x);if(f.isCPU&&Math.abs(f.vx)<1)f.dir=Math.sign(opponent.x-f.x);if(!f.isCPU)f.energy=Math.min(100,f.energy+dt*4);else f.energy=Math.min(100,f.energy+dt*3.4);attackCheck(f,opponent)}
function update(dt){if(active){elapsed+=dt;timeLeft=Math.max(0,60-elapsed);if(timeLeft<=0)endGame(player.hp===enemy.hp?'draw':player.hp>enemy.hp?'player':'enemy');updateFighter(player,dt,enemy);updateFighter(enemy,dt,player);if(Math.abs(player.x-enemy.x)<45){const mid=(player.x+enemy.x)/2;player.x=mid-23;enemy.x=mid+23}updateHUD()}for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;if(p.kind==='spark'){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=360*dt}if(p.life<=0)particles.splice(i,1)}shake=Math.max(0,shake-dt*28)}

function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function drawBackground(){
 const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#527783');sky.addColorStop(.52,'#d7a975');sky.addColorStop(.53,'#34414a');sky.addColorStop(1,'#17242b');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // late afternoon glow
 const glow=ctx.createRadialGradient(495,190,20,495,210,310);glow.addColorStop(0,'#ffd98e66');glow.addColorStop(1,'#ffd98e00');ctx.fillStyle=glow;ctx.fillRect(150,0,690,440);
 // distant rooftops
 ctx.fillStyle='#24343c';for(let i=0;i<17;i++){let x=i*63-16,h=65+((i*37)%85);ctx.fillRect(x,300-h,54,h);ctx.fillStyle='#405359';ctx.fillRect(x+8,302-h,4,h);ctx.fillStyle='#24343c'}
 // Monas-inspired monument
 ctx.fillStyle='#d5bc8c';ctx.beginPath();ctx.moveTo(449,314);ctx.lineTo(464,186);ctx.lineTo(496,186);ctx.lineTo(512,314);ctx.closePath();ctx.fill();ctx.fillStyle='#f0da9c';ctx.beginPath();ctx.moveTo(464,186);ctx.lineTo(480,145);ctx.lineTo(496,186);ctx.closePath();ctx.fill();ctx.fillStyle='#e65d3d';ctx.beginPath();ctx.moveTo(480,143);ctx.lineTo(473,124);ctx.lineTo(480,111);ctx.lineTo(487,124);ctx.closePath();ctx.fill();ctx.fillStyle='#edcf8e';ctx.fillRect(438,311,86,8);ctx.fillRect(429,319,105,8);
 // arena banners
 for(const x of [70,848]){ctx.fillStyle='#392d28';ctx.fillRect(x,176,7,164);ctx.fillStyle='#f0dfc0';ctx.fillRect(x+7,189,72,48);ctx.fillStyle='#df4d3e';ctx.fillRect(x+7,189,72,24);ctx.fillStyle='#f3dfb7';ctx.fillRect(x+7,213,72,24);ctx.fillStyle='#f3dfb7';ctx.beginPath();ctx.moveTo(x+7,237);ctx.lineTo(x+42,254);ctx.lineTo(x+79,237);ctx.closePath();ctx.fill()}
 // crowd rail and crowd
 ctx.fillStyle='#18252b';ctx.fillRect(0,333,960,79);for(let i=0;i<56;i++){const x=i*19-4,base=392+(i%3)*3;ctx.fillStyle=['#b94c3e','#d6ae6e','#466c71','#d4c7a8'][i%4];ctx.beginPath();ctx.arc(x+8,base-23-(i%4)*2,7,0,Math.PI*2);ctx.fill();ctx.fillRect(x+1,base-18,15,22);if(i%6===0){ctx.strokeStyle='#d5bd85';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+8,base-19);ctx.lineTo(x+4,base-31);ctx.moveTo(x+8,base-19);ctx.lineTo(x+14,base-33);ctx.stroke()}}
 ctx.fillStyle='#96764c';ctx.fillRect(0,407,960,17);ctx.fillStyle='#e3c18a';ctx.fillRect(0,407,960,4);
 const floor=ctx.createLinearGradient(0,420,0,540);floor.addColorStop(0,'#9b7952');floor.addColorStop(1,'#4e473e');ctx.fillStyle=floor;ctx.fillRect(0,424,960,116);
 // painted ring perspective
 ctx.strokeStyle='#e9cf9d55';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(480,474,370,76,0,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.ellipse(480,474,255,48,0,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#df554344';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(480,427);ctx.lineTo(480,540);ctx.stroke();
 ctx.fillStyle='#fff0ce';ctx.globalAlpha=.11;ctx.font='1000 36px system-ui';ctx.textAlign='center';ctx.fillText('NUSANTARA',480,490);ctx.globalAlpha=1;
 // vignette
 const v=ctx.createRadialGradient(480,265,190,480,265,610);v.addColorStop(.55,'#00000000');v.addColorStop(1,'#080e16a8');ctx.fillStyle=v;ctx.fillRect(0,0,W,H);
}
function drawFighter(f){const d=f.data,walk=Math.sin(f.walk)*5,air=GROUND-f.y;const hit=f.flash>0;ctx.save();ctx.translate(f.x,f.y);if(f.dir<0)ctx.scale(-1,1);
 // shadow
 ctx.globalAlpha=Math.max(.15,.35-air/250);ctx.fillStyle='#0a1116';ctx.beginPath();ctx.ellipse(0,2,34-air*.045,8-air*.01,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 if(f.attack&&f.attack.type==='special'){ctx.globalAlpha=.2;ctx.fillStyle=d.glow;ctx.beginPath();ctx.ellipse(0,-71,62,69,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
 // legs and shoes
 ctx.strokeStyle=hit?'#fff':d.trim;ctx.lineWidth=14;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-10,-39);ctx.lineTo(-14+walk,-15);ctx.lineTo(-18+walk,-5);ctx.moveTo(10,-39);ctx.lineTo(13-walk,-16);ctx.lineTo(20-walk,-5);ctx.stroke();ctx.fillStyle='#29353b';ctx.beginPath();ctx.ellipse(-22+walk,-4,13,6,-.12,0,Math.PI*2);ctx.ellipse(23-walk,-4,13,6,.12,0,Math.PI*2);ctx.fill();
 // torso
 ctx.fillStyle=hit?'#fff':d.coat;ctx.beginPath();ctx.moveTo(-19,-91);ctx.quadraticCurveTo(-27,-88,-26,-68);ctx.lineTo(-23,-38);ctx.quadraticCurveTo(0,-31,23,-38);ctx.lineTo(26,-68);ctx.quadraticCurveTo(27,-88,19,-91);ctx.closePath();ctx.fill();ctx.strokeStyle='#27343a';ctx.lineWidth=2;ctx.stroke();
 ctx.fillStyle=d.trim;ctx.fillRect(-21,-47,42,7);ctx.fillStyle='#f1d392';ctx.fillRect(-3,-85,6,40);ctx.fillRect(-14,-79,6,6);ctx.fillRect(8,-79,6,6);
 // arms stance or attacks
 let frontX=27,frontY=-73,backX=-28,backY=-72;if(f.attack){const p=f.attack.type==='special'?1-f.attack.t/.48:1-f.attack.t/.29;frontX=35+Math.sin(Math.min(1,p)*Math.PI/2)*25;frontY=-74+(f.attack.type==='special'?-4:0);backX=-23;backY=-70}else if(f.block){frontX=9;frontY=-91;backX=22;backY=-81}
 ctx.lineWidth=11;ctx.lineCap='round';ctx.strokeStyle=hit?'#fff':d.coat;ctx.beginPath();ctx.moveTo(19,-84);ctx.lineTo(frontX,frontY);ctx.moveTo(-19,-83);ctx.lineTo(backX,backY);ctx.stroke();ctx.fillStyle=d.skin;ctx.beginPath();ctx.arc(frontX,frontY,8,0,Math.PI*2);ctx.arc(backX,backY,8,0,Math.PI*2);ctx.fill();
 // collar, face, neck
 ctx.fillStyle=d.trim;ctx.beginPath();ctx.moveTo(-9,-91);ctx.lineTo(0,-76);ctx.lineTo(9,-91);ctx.lineTo(4,-96);ctx.lineTo(-4,-96);ctx.closePath();ctx.fill();ctx.fillStyle=d.skin;ctx.fillRect(-5,-103,10,12);ctx.beginPath();ctx.ellipse(0,-116,19,23,0,0,Math.PI*2);ctx.fill();
 // ears, eye and brow
 ctx.fillStyle=d.skin;ctx.beginPath();ctx.arc(18,-116,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#282522';ctx.beginPath();ctx.arc(10,-119,2.4,0,Math.PI*2);ctx.fill();ctx.fillRect(7,-125,7,2.5);
 if(d.name==='Bung Hatta'){ctx.strokeStyle='#373c3c';ctx.lineWidth=2;ctx.beginPath();ctx.arc(10,-117,5,0,Math.PI*2);ctx.arc(20,-117,5,0,Math.PI*2);ctx.moveTo(15,-117);ctx.lineTo(15,-117);ctx.stroke()}
 // moustache or distinctive details
 if(d.name==='Bung Karno'||d.name==='Jenderal Sudirman'){ctx.fillStyle='#382a24';ctx.beginPath();ctx.ellipse(11,-108,7,2.5,0,0,Math.PI*2);ctx.fill()}
 if(d.name==='Ibu Kartini'||d.name==='Cut Nyak Dien'){ctx.fillStyle=d.trim;ctx.beginPath();ctx.arc(0,-120,23,Math.PI,Math.PI*2);ctx.lineTo(22,-115);ctx.quadraticCurveTo(0,-109,-22,-115);ctx.closePath();ctx.fill();ctx.fillStyle=d.glow;ctx.beginPath();ctx.arc(-17,-121,5,0,Math.PI*2);ctx.fill()}
 else if(d.hat){ctx.fillStyle='#263039';ctx.beginPath();ctx.ellipse(0,-135,24,7,0,0,Math.PI*2);ctx.fill();ctx.fillRect(-16,-149,32,14);ctx.fillStyle=d.trim;ctx.fillRect(-16,-139,32,3)}
 // nameplate glow when super is ready
 if(f.energy>=35){ctx.fillStyle=d.glow;ctx.globalAlpha=.65+Math.sin(elapsed*5)*.25;ctx.beginPath();ctx.arc(0,-159,3,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
 if(f.attack&&f.attack.type==='special'){ctx.strokeStyle=d.glow;ctx.lineWidth=5;ctx.globalAlpha=.7;ctx.beginPath();ctx.arc(45,-77,28,-1.2,.7);ctx.stroke();ctx.globalAlpha=1}
 ctx.restore();
}
function drawParticles(){for(const p of particles){const alpha=Math.max(0,p.life/p.max);ctx.globalAlpha=alpha;if(p.kind==='spark'){ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size*alpha,0,Math.PI*2);ctx.fill()}else{ctx.strokeStyle=p.color;ctx.lineWidth=5*alpha;ctx.beginPath();ctx.arc(p.x,p.y,25+(1-alpha)*48,0,Math.PI*2);ctx.stroke()}}ctx.globalAlpha=1}
function render(){ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawBackground();if(player&&enemy){drawFighter(player);drawFighter(enemy);drawParticles()}ctx.restore()}
function loop(now){const dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);render();requestAnimationFrame(loop)}
setCards();requestAnimationFrame(loop);
</script>
</body>
</html>

